mapper.select:
SELECT a.*, g.goods_name, w.warehouse_name, u.real_name as operator_name FROM biz_stock_adjust a INNER JOIN biz_goods g ON a.goods_id = g.id INNER JOIN biz_warehouse w ON a.warehouse_id = w.id LEFT JOIN sys_user u ON a.operator_id = u.id WHERE 1=1
AND a.adjust_type = #{adjustType}
AND a.warehouse_id = #{warehouseId}
ORDER BY a.create_time DESC
